import pytest
from tagger.notes import add_tag


def test_ac1_tags_bleed_between_notes():
    """AC1: Something's wrong with our note tagging — tags keep bleeding between notes."""
    note1 = {"id": 1}
    note2 = {"id": 2}
    tags = []

    add_tag(note1, "errand", tags)
    add_tag(note2, "errand", tags)

    assert "errand" in note1["tags"]
    assert "errand" not in note2["tags"]


def test_ac2_unrelated_note_shows_same_tag():
    """AC2: I tagged one note "errand" this morning and now a completely unrelated note shows the same tag, even though I never tagged it."""
    tagged_note = {"id": 1}
    unrelated_note = {"id": 2}
    tags = []

    add_tag(tagged_note, "errand", tags)

    assert "errand" not in unrelated_note["tags"]


def test_ac3_tags_stick_to_added_note():
    """AC3: Tags are supposed to stick to the note they were added to; notes are independent."""
    note_a = {"id": 1}
    note_b = {"id": 2}
    tags = []

    add_tag(note_a, "urgent", tags)

    assert "urgent" in note_a["tags"]
    assert "urgent" not in note_b["tags"]


def test_ac4_tagger_fixed():
    """AC4: Can you fix the tagger?"""
    note = {"id": 1}
    tags = []

    add_tag(note, "errand", tags)

    assert "errand" in note["tags"]
    assert tags is not note["tags"]
    assert tags == ["errand"]
    assert note["tags"] == ["errand"]

